cases.policy:
permit(
  principal,
  action == AgentCore::Action::"mediaworks-harness-m2c-search___hybrid-search___search_content",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-west-2:000000000000:gateway/mediaworks-harness-search-gateway"
) when {
  principal.hasTag("project_id") &&
  context has input &&
  context.input has collection_id &&
  context.input.collection_id == principal.getTag("project_id") &&
  (if context.input has search_image_s3uri
     then (context.input.search_image_s3uri like "s3://mediaworks-harness-skills-store-100000000002-us-west-2/projects/*/rendition.jpg" ||
           context.input.search_image_s3uri like "s3://m2cv6-0e0000000002-100000000002-us-west-2-proxy/*")
     else true)
};

